  // softly floating pollen
  for(let i=0;i<15;i++){let x=(i*83+time*11-cam*.2)%(W+20);let y=175+(i*47)%220+Math.sin(time+i)*8;circle(ctx,x,y,1.7,'#fff5b8aa')}
